```matlab
%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%
% H2 State Feedback Controller Design using LMI Formulation
% 
% This MATLAB code designs an H2 state feedback controller that minimizes
% the sum of squared H2 norms of transfer functions from input disturbance
% to output and to control input.
%
% The optimization problem is formulated using the Schur complement lemma
% and bounded real lemma to handle the nonlinearity in the system structure.
%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%

clc
clear all
close all

%% Load and prepare system data
load('data3.mat');
G3 = bj(data3, [5, 5, 5, 5, 1]);
G3_c = d2c(G3);
[A, B, C, D] = ssdata(G3_c);

%% H2 State Feedback Controller Design using LMI Formulation
X = sdpvar(size(A,1), 'symmetric');
Y = sdpvar(size(B,2), size(A,1), 'full');
Z1 = sdpvar(size(C,1), 'symmetric');
Z2 = sdpvar(size(B,2), 'symmetric');

epsilon = 1e-6;

% Stability LMI (Bounded Real Lemma)
LMI1 = [A*X + X*A' - B*Y - Y'*B' + B*B' <= -epsilon*eye(size(A))];

% Positive definiteness
LMI2 = [X >= epsilon*eye(size(A))];

% Schur complement for output term
LMI3 = [[Z1, C*X; X*C', X] >= 0];

% Schur complement for control term
LMI4 = [[Z2, Y; Y', X] >= 0];

LMIs = [LMI1, LMI2, LMI3, LMI4];
Objective = trace(Z1) + trace(Z2);

options = sdpsettings('solver','sedumi','verbose',1);
diagnostics = optimize(LMIs, Objective, options);

if diagnostics.problem == 0
    X_opt = value(X);
    Y_opt = value(Y);
    K = Y_opt / X_opt;

    % Closed-loop analysis
    A_cl = A - B*K;
    sys_cl = ss(A_cl, B, C, D);

    % LQR comparison
    Q_lqr = C'*C + 1e-3*eye(size(A));
    R_lqr = eye(size(B,2));
    [K_lqr,~,~] = lqr(A,B,Q_lqr,R_lqr);
    sys_cl_lqr = ss(A-B*K_lqr,B,C,D);

    % Step response comparison
    figure;
    step(sys_cl, 'b', sys_cl_lqr, 'r--');
    legend('H2 Controller', 'LQR');
    grid on;
else
    error('Optimization failed');
end
