                String countStr = Integer.toString(counts[sum]);
                String empProbStr = df.format(empiricalProbs[sum]);
                String theoProbStr = df.format(theoreticalProbs[sum]);
                double diff = empiricalProbs[sum] - theoreticalProbs[sum];
                String diffStr = df.format(diff);

                // Adjust tabs based on count length for consistent formatting
                String countTabs;
                if (counts[sum] >= 1000) {
                    countTabs = "\t";
                } else if (counts[sum] >= 100) {
                    countTabs = "\t";
                } else {
                    countTabs = "\t\t";
                }

                System.out.println(sum + "\t" + countStr + countTabs + 
                                 empProbStr + "\t\t" + theoProbStr + "\t\t" + diffStr);
            }
        }

        // Answer specific questions
