'use client';

import { collection, getDocs } from 'firebase/firestore';
import { db } from '@/lib/firebase';
import Link from 'next/link';
import { useState, useEffect } from 'react';

export default function DocsNavigation({ currentSlug }) {
  const [docs, setDocs] = useState([]);

  useEffect(() => {
    const fetchDocs = async () => {
      const querySnapshot = await getDocs(collection(db, 'documents'));
      const docsList = querySnapshot.docs.map(doc => ({
        id: doc.id,
        ...doc.data()
      }));
      setDocs(docsList);
    };

    fetchDocs();
  }, []);

  return (
    <nav className="w-64 p-4 border-r">
      <h2 className="text-xl font-semibold mb-4">Documentation</h2>
      <ul className="space-y-2">
        {docs.map((doc) => (
          <li key={doc.id}>
            <Link 
              href={`/docs/${doc.slug}`}
              className={`block px-3 py-2 rounded ${currentSlug === doc.slug ? 'bg-blue-100 text-blue-700' : 'hover:bg-gray-100'}`}
            >
              {doc.title}
            </Link>
          </li>
        ))}
      </ul>
    </nav>
  );
}
```

