// Board drawing
void ChessWindow::drawBoard() {
    const float squareSize = 70.f;
    const sf::Vector2f boardOffset(
        (windowWidth - 8*squareSize)/2, 
        50.f
    );

    for (int row = 0; row < 8; ++row) {
        for (int col = 0; col < 8; ++col) {
            sf::RectangleShape square(sf::Vector2f(squareSize, squareSize));
            square.setPosition(
                boardOffset.x + col*squareSize,
                boardOffset.y + row*squareSize
            );
            square.setFillColor((row+col)%2 ? darkSquare : lightSquare);
            window.draw(square);

            // Draw piece if present
            if (auto piece = board.getPieceAt(row, col)) {
                sf::Sprite pieceSprite(textures[piece->getType()][piece->getColor()]);
                pieceSprite.setPosition(square.getPosition());
                window.draw(pieceSprite);
            }
        }
    }
}

// Rating display example
void RatingWindow::drawRatings() {
    sf::RectangleShape overlay(sf::Vector2f(windowWidth, windowHeight));
    overlay.setFillColor(sf::Color(0, 0, 0, 150));
    window.draw(overlay);

    // Draw window background
    sf::RectangleShape windowBg(sf::Vector2f(600, 400));
    windowBg.setPosition(100, 100);
    windowBg.setFillColor(sf::Color(240, 240, 240));
    window.draw(windowBg);

    // Draw sorted ratings
    auto ratings = RatingManager::getInstance().getSortedRatings();
    for (size_t i = 0; i < ratings.size(); ++i) {
        const auto& [name, stats] = ratings[i];

        // Set color based on win rate
        sf::Color textColor = stats.win_rate > 0.5f ? 
            sf::Color(0, 150, 0) : sf::Color(150, 0, 0);

        // Create and position text
        sf::Text playerText(name, font, 20);
        playerText.setPosition(120, 150 + i*30);
        playerText.setFillColor(textColor);
        window.draw(playerText);

        // Draw other stats similarly...
    }
}

