```javascript
import React, { useState, useEffect, useRef, useCallback } from 'react';
import { View, StyleSheet, PanResponder, Dimensions, Text, Alert, ActivityIndicator, SafeAreaView, TouchableOpacity } from 'react-native';
import axios from 'axios';

const SCREEN_WIDTH = Dimensions.get('window').width;
const SCREEN_HEIGHT = Dimensions.get('window').height;
const CANVAS_WIDTH = SCREEN_WIDTH - 40;
const CANVAS_HEIGHT = SCREEN_HEIGHT - 250;
const MAX_COORDINATE = 2160;
const BATCH_SIZE = 10;

const App = () => {
  const [points, setPoints] = useState([]);
  const [currentBatch, setCurrentBatch] = useState([]);
  const [currentBatchIndex, setCurrentBatchIndex] = useState(0);
  const [userPath, setUserPath] = useState([]);
  const [completedPaths, setCompletedPaths] = useState([]);
  const [isLoading, setIsLoading] = useState(true);

  useEffect(() => {
    // Fetch data from API
    const fetchData = async () => {
      try {
        const response = await axios.get('YOUR_API_ENDPOINT');
        if (Array.isArray(response.data)) {
          setPoints(response.data);
          setIsLoading(false);
        }
      } catch (error) {
        // Fallback to mock data
        const mockData = Array.from({length: 30}, (_, i) => ({
          x: Math.random() * MAX_COORDINATE,
          y: Math.random() * MAX_COORDINATE,
          id: i
        }));
        setPoints(mockData);
        setIsLoading(false);
      }
    };

    fetchData();
  }, []);

  // Update current batch when points or batch index changes
  useEffect(() => {
    if (points.length > 0) {
      const startIdx = currentBatchIndex * BATCH_SIZE;
      const batch = points.slice(startIdx, startIdx + BATCH_SIZE);
      setCurrentBatch(batch);
    }
  }, [points, currentBatchIndex]);

  // Convert coordinates to screen space
  const toScreenCoords = useCallback((point) => {
    const padding = 20;
    return {
      x: padding + (point.x / MAX_COORDINATE) * (CANVAS_WIDTH - 2 * padding),
      y: padding + (point.y / MAX_COORDINATE) * (CANVAS_HEIGHT - 2 * padding)
    };
  }, []);

  // PanResponder for drawing
  const panResponder = useRef(
    PanResponder.create({
      onStartShouldSetPanResponder: () => true,
      onMoveShouldSetPanResponder: () => true,
      onPanResponderGrant: (e) => {
        setUserPath([{x: e.nativeEvent.locationX, y: e.nativeEvent.locationY}]);
      },
      onPanResponderMove: (e) => {
        setUserPath(prev => [...prev, {
          x: e.nativeEvent.locationX,
          y: e.nativeEvent.locationY
        }]);
      },
      onPanResponderRelease: () => {
        // Save completed path and move to next batch
        setCompletedPaths(prev => [...prev, [...userPath]]);
        setUserPath([]);

        // If there are more points, go to next batch
        if ((currentBatchIndex + 1) * BATCH_SIZE < points.length) {
          setCurrentBatchIndex(prev => prev + 1);
        } else {
          // All batches completed - clear final points
          setCurrentBatch([]);
          Alert.alert('Completed', 'All points connected!');
        }
      }
    })
  ).current;

  // Render UI components
  if (isLoading) {
    return (
      <SafeAreaView style={styles.container}>
        <ActivityIndicator size="large" />
      </SafeAreaView>
    );
  }

  return (
    <SafeAreaView style={styles.container}>
      <View style={styles.canvas} {...panResponder.panHandlers}>
        {/* Render completed paths */}
        {completedPaths.map((path, i) => (
          <Path key={`completed-${i}`} points={path} color="green" />
        ))}

        {/* Render current path */}
        {userPath.length > 0 && <Path points={userPath} color="orange" />}

        {/* Render current batch points */}
        {currentBatch.map((point) => {
          const screenPos = toScreenCoords(point);
          return (
            <View 
              key={`point-${point.id}`}
              style={[
                styles.point,
                {left: screenPos.x - 10, top: screenPos.y - 10}
              ]}
            />
          );
        })}
      </View>
    </SafeAreaView>
  );
};

const Path = ({points, color}) => {
  return points.slice(1).map((point, i) => (
    <View
      key={`segment-${i}`}
      style={[
        styles.pathSegment,
        {
          left: Math.min(points[i].x, point.x),
          top: Math.min(points[i].y, point.y),
          width: Math.abs(point.x - points[i].x),
          height: Math.abs(point.y - points[i].y),
          borderColor: color
        }
      ]}
    />
  ));
};

const styles = StyleSheet.create({
  container: {
    flex: 1,
    justifyContent: 'center',
    alignItems: 'center'
  },
  canvas: {
    width: CANVAS_WIDTH,
    height: CANVAS_HEIGHT,
    backgroundColor: 'white',
    position: 'relative'
  },
  point: {
    position: 'absolute',
    width: 20,
    height: 20,
    borderRadius: 10,
    backgroundColor: 'blue'
  },
  pathSegment: {
    position: 'absolute',
    borderWidth: 2
  }
});

export default App;
```

