func NewBudgetOptimizer(categories []string, minWeights, maxWeights []float64, totalBudget float64) *BudgetOptimizer {
	if len(categories) != len(minWeights) || len(categories) != len(maxWeights) {
		panic("categories, minWeights, and maxWeights must have same length")
	}

	for i := range minWeights {
		if minWeights[i] > maxWeights[i] {
			panic(fmt.Sprintf("minWeight[%d] > maxWeight[%d]", i, i))
		}
	}

	expectedReturns := make([]float64, len(categories))
	riskFactors := make([]float64, len(categories))
	for i := range categories {
		expectedReturns[i] = 0.1 + rand.Float64()*0.1
		riskFactors[i] = 0.05 + rand.Float64()*0.15
	}

	return &BudgetOptimizer{
		Categories:      categories,
		MinWeights:      minWeights,
		MaxWeights:      maxWeights,
		TotalBudget:     totalBudget,
		PopulationSize:  100,
		MutationRate:    0.15,
